#requires -Version 5.1
# Inert fixtures only. No scheduling, host inspection, elevation or program launch.
[CmdletBinding()]param([string]$OutputRoot=(Join-Path $env:TEMP 'NikkeAftercareTests'))
$ErrorActionPreference='Stop'
Import-Module (Join-Path $PSScriptRoot 'NikkeRecovery.Core.psm1') -DisableNameChecking
Import-Module (Join-Path $PSScriptRoot 'NikkeRecovery.Integrity.psm1') -DisableNameChecking
Import-Module (Join-Path $PSScriptRoot 'NikkeRecovery.Aftercare.psm1') -DisableNameChecking
Add-Type -AssemblyName System.IO.Compression
$root=Join-Path (Get-CanonicalPath $OutputRoot) ([guid]::NewGuid().ToString('N'));New-ProtectedDirectory $root ([Security.Principal.WindowsIdentity]::GetCurrent().User.Value)
$cases=New-Object 'Collections.Generic.List[object]'
function Check([string]$Name,[scriptblock]$Test){& $Test;$cases.Add([pscustomobject]@{Name=$Name;Passed=$true})}
function Assert($Value,[string]$Message='Assertion failed'){if(-not $Value){throw $Message}}
function Throws([scriptblock]$Action){$caught=$false;try{& $Action|Out-Null}catch{$caught=$true};Assert $caught 'Expected operation to be refused'}
function ZipFixture([string]$Name,[object[]]$Entries){$path=Join-Path $root ($Name+'.zip');$s=[IO.File]::Open($path,[IO.FileMode]::CreateNew);$z=[IO.Compression.ZipArchive]::new($s,[IO.Compression.ZipArchiveMode]::Create,$true);try{foreach($f in $Entries){$e=$z.CreateEntry($f.Name);$w=New-Object IO.StreamWriter($e.Open(),(New-Object Text.UTF8Encoding($false)));try{$w.Write([string]$f.Text)}finally{$w.Dispose()}}}finally{$z.Dispose();$s.Dispose()};return $path}
function Baseline($Zip){return New-NikkeVendorBaseline $Zip (Get-NikkeFileDigest $Zip).SHA256 'FixtureApp' '1.0.0' 'https://vendor.example/fixture.zip'}
$zip=ZipFixture 'vendor' @(@{Name='bin/app.exe';Text='INERT trusted binary fixture'},@{Name='bin/plugin.dll';Text='INERT trusted library fixture'},@{Name='settings.json';Text='{"original":true}'})
$baseline=Baseline $zip;$baselinePath=Join-Path $root 'baseline.json';Save-Json $baselinePath $baseline;$baselineHash=(Get-NikkeFileDigest $baselinePath).SHA256
$app=Join-Path $root 'FixtureApp';[IO.Directory]::CreateDirectory((Join-Path $app 'bin'))|Out-Null
[IO.File]::WriteAllText((Join-Path $app 'bin\app.exe'),'INERT changed binary fixture')
[IO.File]::WriteAllText((Join-Path $app 'settings.json'),'USER CONFIG MUST SURVIVE')
[IO.File]::WriteAllText((Join-Path $app 'unlisted.dll'),'INERT extra file')
$before=(Get-NikkeFileDigest (Join-Path $app 'bin\app.exe')).SHA256
$configBefore=(Get-NikkeFileDigest (Join-Path $app 'settings.json')).SHA256
$plan=New-NikkeIntegrityPlan $baseline $baselineHash $app
Check 'Pinned package yields metadata without claiming publisher authentication' {Assert ($baseline.Files.Count -eq 3 -and -not $baseline.PublisherAuthenticityVerified -and $baseline.Trust -eq 'OperatorPinnedArchive')}
Check 'Wrong package hash rejected' {Throws {New-NikkeVendorBaseline $zip ('0'*64) 'Fixture' '1' 'https://vendor.example/a.zip'}}
Check 'Non-HTTPS provenance rejected' {Throws {New-NikkeVendorBaseline $zip (Get-NikkeFileDigest $zip).SHA256 'Fixture' '1' 'http://vendor.example/a.zip'}}
Check 'Pinned JSON mutation rejected' {Throws {Read-NikkePinnedJson $baselinePath ('0'*64)}}
Check 'ZIP traversal rejected before extraction' {$bad=ZipFixture 'traversal' @(@{Name='../escape.dll';Text='INERT'});Throws {Baseline $bad};Assert (-not(Test-Path -LiteralPath (Join-Path $root 'escape.dll')))}
Check 'Case-insensitive ZIP collision rejected' {$bad=ZipFixture 'collision' @(@{Name='a.dll';Text='a'},@{Name='A.dll';Text='b'});Throws {Baseline $bad}}
Check 'ADS and reserved names refused' {Throws {ConvertTo-NikkeRelativePath 'app.dll:payload'};Throws {ConvertTo-NikkeRelativePath 'CON.dll'};Throws {ConvertTo-NikkeRelativePath 'a.\b.dll'}}
Check 'Absolute paths refused' {Throws {ConvertTo-NikkeRelativePath 'C:\escape.dll'};Throws {ConvertTo-NikkeRelativePath '\\server\x.dll'}}
Check 'Broad target roots refused' {Throws {New-NikkeIntegrityPlan $baseline $baselineHash $env:USERPROFILE};Throws {New-NikkeIntegrityPlan $baseline $baselineHash $env:SystemRoot}}
Check 'Mismatch and missing binary distinguished' {Assert (@($plan.Files|Where-Object Status -eq 'Mismatch').Count -eq 2);Assert (@($plan.Files|Where-Object Status -eq 'Missing').Count -eq 1)}
Check 'Unlisted binary is retained for review' {Assert ($plan.UnlistedBinaries.Count -eq 1 -and -not $plan.UnlistedBinaries[0].AutomaticRemoval)}
Check 'User configuration is ineligible for replacement' {Assert (-not @($plan.Files|Where-Object RelativePath -eq 'settings.json')[0].RepairEligible);Throws {Invoke-NikkePinnedRepair $plan $baseline $zip @('settings.json') (Join-Path $root 'evidence')}}
Check 'Budget exhaustion is incomplete, not clean' {$limited=New-NikkeIntegrityPlan $baseline $baselineHash $app -MaxFiles 1;Assert (-not $limited.CoverageComplete -and @($limited.Files|Where-Object Status -eq 'Unexamined').Count -gt 0)}
Check 'Archive and edited baseline disagreement rejected' {$bad=$baseline|ConvertTo-Json -Depth 10|ConvertFrom-Json;$bad.Files[0].SHA256='0'*64;Throws {Invoke-NikkePinnedRepair $plan $bad $zip @('bin\app.exe') (Join-Path $root 'evidence')}}
Check 'Repair evidence cannot live inside application' {Throws {Invoke-NikkePinnedRepair $plan $baseline $zip @('bin\app.exe') (Join-Path $app 'evidence')}}
Check 'Changed target after planning is retained' {[IO.File]::WriteAllText((Join-Path $app 'bin\app.exe'),'LATER VERSION');$r=Invoke-NikkePinnedRepair $plan $baseline $zip @('bin\app.exe') (Join-Path $root 'evidence');Assert ($r.Failed -eq 1 -and [IO.File]::ReadAllText((Join-Path $app 'bin\app.exe')) -eq 'LATER VERSION');[IO.File]::WriteAllText((Join-Path $app 'bin\app.exe'),'INERT changed binary fixture')}
Check 'File appearing after missing plan is not overwritten' {[IO.File]::WriteAllText((Join-Path $app 'bin\plugin.dll'),'NEW USER FILE');$r=Invoke-NikkePinnedRepair $plan $baseline $zip @('bin\plugin.dll') (Join-Path $root 'evidence');Assert ($r.Failed -eq 1 -and [IO.File]::ReadAllText((Join-Path $app 'bin\plugin.dll')) -eq 'NEW USER FILE');Move-Item -LiteralPath (Join-Path $app 'bin\plugin.dll') -Destination (Join-Path $root 'appeared-file.preserved')}
Check 'Selected binary repair preserves original twice and restores missing file' {$script:repair=Invoke-NikkePinnedRepair $plan $baseline $zip @('bin\app.exe','bin\plugin.dll') (Join-Path $root 'evidence');Assert ($script:repair.Completed -eq 2 -and $script:repair.Failed -eq 0);$r=@($script:repair.Outcomes|Where-Object RelativePath -eq 'bin\app.exe')[0];Assert ((Get-NikkeFileDigest $r.Preserved).SHA256 -eq $before);Assert ((Get-NikkeFileDigest $r.AtomicBackup).SHA256 -eq $before)}
Check 'Configuration and unlisted binaries survive repair' {Assert ((Get-NikkeFileDigest (Join-Path $app 'settings.json')).SHA256 -eq $configBefore);Assert ([IO.File]::ReadAllText((Join-Path $app 'unlisted.dll')) -eq 'INERT extra file')}
Check 'Recheck verifies repaired binary hashes without whole-host verdict' {$after=New-NikkeIntegrityPlan $baseline $baselineHash $app;Assert (@($after.Files|Where-Object Status -eq 'Match').Count -eq 2 -and -not $after.WholeHostCleanClaim)}
Check 'Extra NTFS stream prevents replacement' {$p=New-NikkeIntegrityPlan $baseline $baselineHash $app;[IO.File]::WriteAllText((Join-Path $app 'bin\app.exe'),'INERT changed again');$p=New-NikkeIntegrityPlan $baseline $baselineHash $app;Set-Content -LiteralPath (Join-Path $app 'bin\app.exe') -Stream 'FixtureExtra' -Value 'retain me';$r=Invoke-NikkePinnedRepair $p $baseline $zip @('bin\app.exe') (Join-Path $root 'evidence');Assert ($r.Failed -eq 1 -and [IO.File]::ReadAllText((Join-Path $app 'bin\app.exe')) -eq 'INERT changed again')}
$inventory=[pscustomobject]@{TargetSid='S-1-5-21-1-2-3-1001';WorkerCompleted=$true;Errors=@();Coverage=[pscustomobject]@{MissingOrUnexaminedFiles=0;UnresolvedCommandsOrShortcuts=0};InstalledPrograms=@();LaunchRelationships=@();ReferencedFiles=@();BrowserPolicies=@();ConfirmedReferences=@()}
$summary=[pscustomobject]@{Verdict='NoKnownActiveIndicatorsWithinScope';RemainingKnownActiveIndicators=0;MappedDllProcesses=@();Issues=@();ProcessCoverage=[pscustomobject]@{ReadErrors=0;EmptyModuleLists=0}}
Check 'Reboot observation remains scope-limited' {$a=New-NikkeAftercareAssessment $summary $inventory $summary $inventory 'boot2' 'boot1';Assert ($a.NewBootObserved -and $a.Recurrence -eq 'NoKnownIndicatorsAfterRestartWithinScope' -and -not $a.WholeHostCleanClaim)}
Check 'Incomplete reboot observation stays inconclusive' {$partial=$inventory|ConvertTo-Json -Depth 10|ConvertFrom-Json;$partial.WorkerCompleted=$false;$a=New-NikkeAftercareAssessment $summary $partial $summary $inventory 'boot2' 'boot1';Assert ($a.Recurrence -eq 'InconclusiveAfterRestart' -and $a.Severity -eq 'ReviewRequired')}
Check 'Returned known indicators alert after restart' {$bad=$summary|ConvertTo-Json -Depth 10|ConvertFrom-Json;$bad.RemainingKnownActiveIndicators=1;$a=New-NikkeAftercareAssessment $bad $inventory $summary $inventory 'boot2' 'boot1';Assert ($a.Recurrence -eq 'KnownIndicatorsAfterRestart' -and $a.Severity -eq 'KnownIndicatorsRemain')}
Check 'Changed startup command creates review, not malware verdict' {$changed=$inventory|ConvertTo-Json -Depth 10|ConvertFrom-Json;$changed.LaunchRelationships=@([pscustomobject]@{Kind='Service';Source='Fixture';Name='Fixture';Command='C:\Fixture\new.exe';Arguments='';FilePath='C:\Fixture\new.exe'});$a=New-NikkeAftercareAssessment $summary $changed $summary $inventory;Assert ($a.Changes.Count -eq 1 -and $a.Severity -eq 'ReviewRequired' -and $a.KnownIndicators -eq 0)}
Check 'Alert fingerprint stable across repeated equal observations' {$a=New-NikkeAftercareAssessment $summary $inventory;$b=New-NikkeAftercareAssessment $summary $inventory;Assert ($a.AlertSignature -eq $b.AlertSignature)}
Check 'Unreviewed changes persist without repeated new-change notifications' {$changed=$inventory|ConvertTo-Json -Depth 10|ConvertFrom-Json;$changed.LaunchRelationships=@([pscustomobject]@{Kind='Service';Source='Fixture';Name='Fixture';Command='C:\Fixture\new.exe';Arguments='';FilePath='C:\Fixture\new.exe'});$a=New-NikkeAftercareAssessment $summary $changed $summary $inventory;$b=New-NikkeAftercareAssessment $summary $changed $summary $changed -PendingChanges $a.PendingChanges;Assert ($b.Changes.Count -eq 0 -and $b.PendingChanges.Count -eq 1 -and $b.Severity -eq 'ReviewRequired' -and $a.AlertSignature -eq $b.AlertSignature)}
Check 'Acknowledging snapshot changes cannot dismiss known indicators' {$bad=$summary|ConvertTo-Json -Depth 10|ConvertFrom-Json;$bad.RemainingKnownActiveIndicators=1;$a=New-NikkeAftercareAssessment $bad $inventory -PendingChanges @();Assert ($a.Severity -eq 'KnownIndicatorsRemain')}
Check 'Different user inventories cannot be compared' {$other=$inventory|ConvertTo-Json -Depth 10|ConvertFrom-Json;$other.TargetSid='S-1-5-21-4-5-6-1001';Throws {New-NikkeAftercareAssessment $summary $inventory $summary $other}}
Check 'Baseline mismatches participate in aftercare alerts' {$a=New-NikkeAftercareAssessment $summary $inventory -IntegrityPlans @($plan);Assert ($a.IntegrityFindings.Count -ge 3 -and $a.Severity -eq 'ReviewRequired')}
Check 'Task is current-user limited, periodic and login-triggered' {[xml]$task=New-NikkeAftercareTaskXml (Join-Path $PSScriptRoot 'Invoke-NikkeAftercare.ps1') (Join-Path $root 'state') $inventory.TargetSid 6;$script:task=$task;Assert ($task.Task.Principals.Principal.RunLevel -eq 'LeastPrivilege' -and $task.Task.Principals.Principal.LogonType -eq 'InteractiveToken');Assert ($task.Task.Triggers.TimeTrigger.Repetition.Interval -eq 'PT6H' -and $task.Task.Triggers.LogonTrigger.UserId -eq $inventory.TargetSid);Assert ($task.Task.Settings.MultipleInstancesPolicy -eq 'IgnoreNew' -and $task.Task.Actions.Exec.Arguments -notmatch '-Mode Apply')}
Check 'Task XML escapes path data' {[xml]$x=New-NikkeAftercareTaskXml (Join-Path $PSScriptRoot 'Invoke-NikkeAftercare.ps1') (Join-Path $root 'state & review') $inventory.TargetSid 6;Assert ($x.Task.Actions.Exec.Arguments.Contains('state & review'))}
Check 'Invalid task interval rejected' {Throws {New-NikkeAftercareTaskXml (Join-Path $PSScriptRoot 'Invoke-NikkeAftercare.ps1') $root $inventory.TargetSid 0}}
Check 'Dashboard cannot inject HTML from reports' {$a=New-NikkeAftercareAssessment $summary $inventory;$a.Interpretation='<script>bad()</script>';$p=Join-Path $root 'STATUS.html';Write-NikkeAftercareDashboard $p $a '<img src=x>';Assert (-not [IO.File]::ReadAllText($p).Contains('<script>'));Assert ([IO.File]::ReadAllText($p).Contains('&lt;img'))}
Check 'Atomic state update preserves a complete JSON object' {$p=Join-Path $root 'state.json';Save-NikkeAtomicJson $p @{Generation=1};Save-NikkeAtomicJson $p @{Generation=2};Assert ((Get-Content -Encoding UTF8 -Raw -LiteralPath $p|ConvertFrom-Json).Generation -eq 2)}
Check 'Repeated private directory protection needs no SACL privilege' {$p=Join-Path $root 'repeat-protection';$sid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;New-ProtectedDirectory $p $sid;New-ProtectedDirectory $p $sid;$acl=Get-Acl -LiteralPath $p;Assert $acl.AreAccessRulesProtected;foreach($rule in $acl.GetAccessRules($true,$true,[Security.Principal.SecurityIdentifier])){Assert ($rule.IdentityReference.Value -in @($sid,'S-1-5-18','S-1-5-32-544'))}}
Check 'Aftercare will not take over an unrelated populated directory' {$p=Join-Path $root 'unrelated';[IO.Directory]::CreateDirectory($p)|Out-Null;[IO.File]::WriteAllText((Join-Path $p 'user.txt'),'USER DATA');$acl=(Get-Acl -LiteralPath $p).Sddl;Throws {Initialize-NikkeAftercareState $p ([Security.Principal.WindowsIdentity]::GetCurrent().User.Value)};Assert ((Get-Acl -LiteralPath $p).Sddl -eq $acl)}
Check 'Initialized aftercare store can be reused by its owner' {$p=Join-Path $root 'owned-state';$sid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;Initialize-NikkeAftercareState $p $sid;Initialize-NikkeAftercareState $p $sid;Assert (Test-Path -LiteralPath (Join-Path $p 'aftercare-owner.json'))}
Check 'Every shipped PowerShell source parses' {foreach($f in @(Get-ChildItem -LiteralPath $PSScriptRoot -File|Where-Object Extension -in @('.ps1','.psm1'))){$t=$null;$e=$null;[Management.Automation.Language.Parser]::ParseFile($f.FullName,[ref]$t,[ref]$e)|Out-Null;if($e.Count){throw ($f.Name+': '+($e.Message -join '; '))}}}
$report=[pscustomobject]@{At=(Get-Date -Format o);PowerShell=$PSVersionTable.PSVersion.ToString();Passed=$cases.Count;Cases=$cases.ToArray();InertFixturesOnly=$true;HostScanStarted=$false;HostApplicationRepaired=$false;ScheduledTaskRegistered=$false;ReportDirectory=$root}
Save-Json (Join-Path $root 'results.json') $report
[pscustomobject]@{PowerShell=$report.PowerShell;Passed=$cases.Count;Results=(Join-Path $root 'results.json')}|ConvertTo-Json
